<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$labels=['PENDING'=>'Chờ xác nhận','CONFIRMED'=>'Đã xác nhận','PROCESSING'=>'Đang xử lý','SHIPPING'=>'Đang giao','DELIVERED'=>'Đã giao','CANCELLED'=>'Đã hủy','RETURNED'=>'Đã trả hàng']; ?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Đơn hàng</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-slate-950 text-slate-100"><main class="mx-auto max-w-5xl p-5 pt-10"><a class="text-blue-300" href="?page=home">← Cửa hàng</a><h1 class="my-5 text-3xl font-bold">Đơn hàng của tôi</h1><?php if($error): ?><p class="rounded bg-red-900 p-3"><?= $e($error) ?></p><?php endif ?><?php if($message): ?><p class="rounded bg-emerald-900 p-3"><?= $e($message) ?></p><?php endif ?><?php foreach($orders as $o): ?><article class="my-4 rounded-xl bg-slate-900 p-5"><div class="flex flex-wrap justify-between gap-3"><strong><?= $e($o['order_code']) ?></strong><span><?= $e($labels[$o['order_status']]??$o['order_status']) ?></span><span><?= $e($o['created_at']) ?></span></div><ul class="my-3 list-inside list-disc"><?php foreach($o['items'] as $i): ?><li><?= $e($i['product_name']) ?> <?= $e($i['variant_name']) ?> × <?= (int)$i['quantity'] ?> — <?= number_format((float)$i['subtotal'],0,',','.') ?> ₫</li><?php endforeach ?></ul><p>Tổng: <b><?= number_format((float)$o['total_amount'],0,',','.') ?> ₫</b> · Thanh toán <?= $e($o['payment_method']) ?> · <?= $e($o['payment_status']) ?></p><?php if($o['order_status']==='PENDING' && $o['payment_status']==='PENDING'): ?><form method="post" class="mt-4 flex flex-wrap gap-2"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="order_code" value="<?= $e($o['order_code']) ?>"><input required minlength="3" maxlength="500" name="reason" placeholder="Lý do hủy đơn" class="flex-1 rounded bg-slate-800 p-2"><button class="rounded bg-red-700 px-4 py-2">Hủy đơn</button></form><?php endif ?></article><?php endforeach ?><?php if(!$orders): ?><p>Bạn chưa có đơn hàng nào.</p><?php endif ?></main></body></html>
